"""Rank bucketing helpers for MoE LoRA tensors."""

from __future__ import annotations

from bisect import bisect_left

from kestrel_kernels.moe.api import MoeLoraState


# Logical per-expert LoRA ranks may start at 1. Ranks below 8 use the rank-8
# storage/compile bucket; larger ranks keep 16-byte BF16 row alignment.
LORA_RANK_GRANULARITY = 8
LORA_RANK_BUCKETS = (8, 16, 32, 64, 128, 256, 512)
LORA_MAX_RANK = LORA_RANK_BUCKETS[-1]


def validate_lora_rank(rank: int) -> None:
    rank = int(rank)
    if rank <= 0:
        return
    if rank > LORA_MAX_RANK or (
        rank >= LORA_RANK_GRANULARITY and rank % LORA_RANK_GRANULARITY != 0
    ):
        raise ValueError(
            "CuTe MoE LoRA per-expert rank must be 1 through 7 or a multiple "
            f"of {LORA_RANK_GRANULARITY} and <= {LORA_MAX_RANK}; got {rank}"
        )


def lora_rank_bucket(rank: int) -> int:
    rank = int(rank)
    validate_lora_rank(rank)
    if rank <= 0:
        return 0
    return LORA_RANK_BUCKETS[bisect_left(LORA_RANK_BUCKETS, rank)]


def lora_a_rank(lora: MoeLoraState, down: bool) -> int:
    return lora_rank_bucket(int((lora.down_a if down else lora.up_a).shape[1]))


__all__ = [
    "LORA_RANK_GRANULARITY",
    "LORA_MAX_RANK",
    "LORA_RANK_BUCKETS",
    "lora_a_rank",
    "lora_rank_bucket",
    "validate_lora_rank",
]
